terraform {
  required_providers {
    google = { source = "hashicorp/google", version = "~> 5.0" }
  }
  backend "gcs" {
    bucket = "satish-tf-state"
    prefix = "orders-pipeline"
  }
}

provider "google" {
  project = "orders-pipeline-prod"
  region  = "us-central1"
}

resource "google_storage_bucket" "orders_raw" {
  name     = "satish-pipeline-orders-raw"
  location = "US"

  lifecycle_rule {
    condition { age = 90 }
    action    { type = "SetStorageClass", storage_class = "COLDLINE" }
  }
}

module "dataproc_cluster" {
  source       = "./modules/dataproc-ephemeral"
  project_id   = "orders-pipeline-prod"
  cluster_name = "orders-pipeline-cluster"
}

